class Solution:
    def topKFrequent(self, nums: List[int], k: int) -> List[int]:

        hmap, res = {}, []

        for number in nums:
            hmap[number] = 1 + hmap.get(number, 0)

        for _ in range(k, 0, -1):
            max_key = max(hmap, key=hmap.get)
            res.append(max_key)
            hmap.pop(max_key)

        return res

