    def permute(self, nums: List[int]) -> List[List[int]]:

        res = []
        def dfs(cur, temp):
            if len(temp) == len(nums):
                res.append(temp.copy())
                return
            for i in range(len(cur)):
                temp.append(cur[i])
                dfs(cur[:i] + cur[i+1:], temp)
                temp.pop()

        dfs(nums, [])
        return res

