def generateSubset(nums):
      if not nums:
         return [[]]
      tail = generateSubset(nums[1:])
      currentValue = nums[0]
      output = []
      for subset in tail:
             output.append(subset)
             output.append([currentValue] + subset)
      return output
return generateSubset(nums)

