def search(list, key):
    l = 0
    h = len(list)-1
    for i in range(len(list)):
        mid = (l + h) // 2
        if list[mid] == key:
            globals()['pos'] = mid
            return True
        else:
            if list[mid] < key:
                l = mid + 1
            else:
                h = mid - 1

    return False


