Just Use the Topological ordering to solve the problem, i think he is misunderstood the problem. I used kahn's algorithm to use this problem

from collections import defaultdict 


"""Try to solve the problem using the Topological Sorting"""


class Kahn: 
  def run(self, edges, V):
    indegree_arr = [0 for _ in range(V)]
    q = []
    topo_arr = []
    adj = defaultdict(list)

    for i, edge in enumerate(edges): 
        u, v = edge
        indegree_arr[v] += 1 
        adj[u].append(v)

    for i, val in enumerate(indegree_arr): 
      if val == 0:
        q.append(i)

    while q: 
      node = q.pop(0)
      topo_arr.append(node)

      nb = adj[node]
      for i, n in enumerate(nb):
        indegree_arr[n] -= 1 
        if indegree_arr[n] == 0:
          q.append(n)

    return topo_arr

class Solution:
    def canFinish(self, numCourses: int, prerequisites: List[List[int]]) -> bool:
        k = Kahn()
        topo_arr = k.run(prerequisites, numCourses)
        if not topo_arr or len(topo_arr) != numCourses:
            return False 

        return True

