class Solution {
public:
    int height(TreeNode *root)
    {
        if (!root)
            return 0;

        int lsh = 0, rsh = 0;

        lsh = height(root->left);
        rsh = height(root->right);

        if (lsh > rsh)
            return lsh+1;
        else
            return rsh+1;
    }

    int BalanceFactor(TreeNode *root)
    {
        if (!root)
            return 0;

        int lsh = 0, rsh = 0;
        lsh = height(root->left);
        rsh = height(root->right);

        return lsh - rsh;
    }

    bool isBalanced(TreeNode* root) {

        if (!root)
            return true;

        if (BalanceFactor(root) == 1 || BalanceFactor(root) == 0 || BalanceFactor(root) == -1)
            return true;


        return false;

    }
};

