def groupAnagrams(strs: list[str]):
    sorted_strs = [''.join(sorted(s)) for s in strs]
    res = {}
    for i, s in enumerate(sorted_strs):
        if s in res:
            res[s].append(strs[i])
        else:
            res[s] = [strs[i]]
    return list(res.values())

Simple java solution:
class Solution {
    List<List<Integer>> result = new ArrayList<>();

    public List<List<Integer>> permute(int[] nums) {
        rec(nums, new HashSet<>(), new ArrayList<>());
        return result;
    }

    private void rec(int[] nums, Set<Integer> used, List<Integer> temp) {
        if (temp.size() == nums.length) {
            result.add(temp);
        }
        for (int i=0; i < nums.length; i++) {
            if (!used.contains(i)) {
                Set<Integer> newUsed = new HashSet(used);
                newUsed.add(i);
                List<Integer> newTemp = new ArrayList<>(temp);
                newTemp.add(nums[i]);
                rec(nums, newUsed, newTemp);
            }
        }
    }


}

