   def isPlanidrome(self , s):
        start = 0
        end = len(s) - 1

        while start < end:
            if self.isalpha(s[start]) and self.isalpha(s[end]):
                if s[start].lower() == s[end].lower():
                    start += 1
                    end -= 1

                else:
                    return False

            else:
                if not self.isalpha(s[start]):
                    start += 1

                if not self.isalpha(s[end]):
                    end -= 1    

        return True   

    def isalpha(self , c):
        return (ord('A') <= ord(c) <= ord('Z') or 
                ord('a') <= ord(c) <= ord('z') or 
                ord('0') <= ord(c) <= ord('9'))

