var permute = function(nums) {
    if (nums.length <= 2) return (nums.length == 1) ?[ [nums[0]]] : [nums, [nums[1], nums[0]]]
    return nums.reduce(( ans  , num ,i)=>  {
            let restPermute = permute([...nums.slice(0, i), ...nums.slice(i + 1)])
            return ans.concat([...restPermute.map(x => [num, ...x])])
        },[])
};

