Tweaked the solution for Course Schedule 1 (NeetCode) to solve the problem for Course Schedule 2:


class Solution:
    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        # map each course to prereq list
        preMap = {i:[] for i in range(numCourses)}
        for crs, pre in prerequisites:
            preMap[crs].append(pre)

        # visitSet = all courses along current DFS path
        visitSet = set()
        # path to store the course order
        path = []

        def dfs(crs):
            if crs in visitSet:
                return False
            if preMap[crs] == []:
                if crs not in path:
                    path.append(crs)
                return True

            visitSet.add(crs)
            for pre in preMap[crs]:
                if not dfs(pre): 
                    return False
            visitSet.remove(crs)
            preMap[crs] = []
            if crs not in path:
                path.append(crs)
            return True

        for crs in range(numCourses):
            if not dfs(crs):
                return []
        return path

