1ms solution with Kotlin:

class Solution {
    fun generateParenthesis(n: Int): List<String> {
        val res = mutableListOf<String>()

        fun helper(str: String, open: Int, close: Int) {
            if (close > open) {
                return
            }
            if (open == n && close == n) {
                res += str
            } else if (open == n) {
                helper(str + ")", open, close + 1)
            } else if (close == n) {
                helper(str + "(", open + 1, close)
            } else {
                helper(str + "(", open + 1, close)
                helper(str + ")", open, close + 1)
            }
        }

        helper("(", 1, 0)

        return res
    }
}

