class Solution {
public:
    bool checkInclusion(string s1, string s2) {
    unordered_map<char, int> check;
    unordered_map<char, int> record;
    int l, r;
    l=0;
    r=0;
    for (int i = 0; i < s1.length(); i++)
    {   
        check[s1[i]]++;
    }
    if (s1.length() > s2.length())
    {
        return false;
    }
    else{
        while(r<s2.length()){
            record[s2[r]]++;
            if(record[s2[r]]>check[s2[r]]){
                while(l<=r){
                    record[s2[l]]--;
                    l++;
                    if(record[s2[r]]==check[s2[r]]){
                        break;
                    }
                }
            }
            if((r-l+1)==s1.length()){
                return true;
            }
            r++;
        }
        return false;
    }
    }
};

