import random

class Player:
    def __init__(self, name, health=100, attack=10):
        self.name = name
        self.health = health
        self.attack = attack

    def is_alive(self):
        return self.health > 0

    def take_damage(self, damage):
        self.health -= damage

    def attack_enemy(self, enemy):
        damage = random.randint(1, self.attack)
        enemy.take_damage(damage)
        return damage

class Enemy:
    def __init__(self, name, health=50, attack=8):
        self.name = name
        self.health = health
        self.attack = attack

    def is_alive(self):
        return self.health > 0

    def take_damage(self, damage):
        self.health -= damage

    def attack_player(self, player):
        damage = random.randint(1, self.attack)
        player.take_damage(damage)
        return damage

def main():
    player_name = input("Enter your name: ")
    player = Player(player_name)
    enemy = Enemy("Evil Goblin")

    print(f"Welcome, {player.name}! You encounter a {enemy.name}.")

    while player.is_alive() and enemy.is_alive():
        print("\n" + "=" * 30)
        print(f"{player.name}: {player.health} HP")
        print(f"{enemy.name}: {enemy.health} HP")
        print("=" * 30 + "\n")

        action = input("Do you want to (a)ttack or (q)uit? ").lower()

        if action == 'a':
            damage_dealt = player.attack_enemy(enemy)
            print(f"You deal {damage_dealt} damage to {enemy.name}!")

            damage_taken = enemy.attack_player(player)
            print(f"{enemy.name} attacks! You take {damage_taken} damage.")

        elif action == 'q':
            print("You quit the game. Bye!")
            break

        else:
            print("Invalid action. Try again.")

    if player.is_alive():
        print("Congratulations! You defeated the enemy.")
    else:
        print("Game over. You were defeated by the enemy.")

if __name__ == "__main__":
    main()

