function numDecodings(s: string): number {
    let lastOne = 1, lastTwo = 0;

    for(let i = s.length - 1; i >= 0; i--) {
        const num = +s[i];
        const tempLastOne = lastOne;

        if(num === 0) {
            lastOne = 0;
        } 

        const nextNum = +s.slice(i, i + 2);

        if(nextNum >= 10 && nextNum <= 26){
            lastOne += lastTwo;
        }    

        lastTwo = tempLastOne;
    }

    return lastOne;
}

