We go through list to the end and do all job at bubbling phase

var reverseList = function(head) {
    function reverse(prev, current) {
        if (!current) {
            return prev;
        }

        const head = reverse(current, current.next);
        current.next = prev;

        return head;
    }

    return reverse(null, head);
};

