void Invert_BinaryTree(Node* root){
    //Base Case
    if(root==NULL){
        return;
    }

    //Recursive case
    Node* temp;
    temp=root->left;
    root->left=root->right;
    root->right=temp;

    Invert_BinaryTree(root->left);
    Invert_BinaryTree(root->right);
    return;
}


