    def combinationSum(self, candidates: List[int], target: int) -> List[List[int]]:
        res = []
        def backtrack(i, cur):
            cursum = sum(cur)
            if cursum == target:
                res.append(cur.copy())
                return
            if i >= len(candidates) or cursum > target:
                return False

            for j in range(i, len(candidates)):
                backtrack(j, cur + [candidates[j]])

        backtrack(0, [])
        return res

