function draw(){
  //random color
  var r = random(248,184)
  var g = random(16,43)
  var b = random(221,168)

  fill(r, g, b);
  noStroke()
  rect(x, y, 6, 6);
  //random direction
  var r = floor(random(4));
  //step size
  var stepsize = 6;
  //which direction
  switch(r){
    case 0:
      x = x + stepsize;
      break;
    case 1:
      x = x - stepsize;
      break;
    case 2:
      y = y + stepsize;
      break;
    case 3:
      y = y - stepsize;
      break;
  };
  //out of window
  if (x < 0 || y < 0 || y > height || x > width) {
    x = random(width);
    y = random(height);
  }
}

