class Solution {
    public boolean dfs(int node , Set<Integer> visitedSet, Map<Integer,List<Integer>> map){
        if(visitedSet.contains(node)) return false;
        if(map.get(node).isEmpty()) return true;
        visitedSet.add(node);
        for(int pre : map.get(node))
            if(!dfs(pre,visitedSet,map)) return false;
        visitedSet.remove(node);
        map.put(node,new ArrayList<>());
        return true;
    }
    public boolean canFinish(int numCourses, int[][] prerequisites) {
        // 1- create hashmap with course and prereq
        Map<Integer, List<Integer>> map = new HashMap<>();
        for(int i = 0 ; i < numCourses ; i++)
            map.put(i, new ArrayList<>());

        //puting prereq
        for(int[] pair : prerequisites){
            int course = pair[0];
            int pre = pair[1];
            map.get(course).add(pre);
        }

        // 2 - create a visit set
        Set<Integer> visitedSet = new HashSet<>();

        // 3 - run dfs on all nodes
        for(int j = 0 ; j < numCourses; j++)
            if(!dfs(j,visitedSet,map)) return false;

        return true;
    }
}

