I much easier, more ituitive solution can be implemented with a deque (granted it will use o(n) memory). We can iterate through each node and add the value to a deque. Then we can go back and fourth between popping left and right to reorder the list.
from collections import deque
class Solution:
    def reorderList(self, head: Optional[ListNode]) -> None:
        cur = head
        deq = deque([])
        while cur:
            deq.append(cur.val)
            cur = cur.next
        count = 2
        newcur = head
        while deq:
            if count % 2 == 0:
                newcur.val = deq.popleft()
                count += 1
            else:
                newcur.val = deq.pop()
                count += 1
            newcur = newcur.next

Better recursive solution in C++
Node* reverseList(Node* head, Node* previousNode = nullptr){
    if(head==nullptr){
        return previousNode;
    }
    Node* newHead {reverseList(head->next, head)};
    head->next = previousNode;
    return newHead;
}

