# recursion + memo (TOP - DOWN DP)
def coinChange(self, coins, amount):
        cache = {}
        def helper(i, amount):
            if amount == 0: return 0
            if amount < 0 or i == len(coins): return float('inf')
            if (i, amount) in cache:
                return cache[(i, amount)]
            cache[(i, amount)] = helper(i + 1, amount)
            if coins[i] <= amount:
                include = 1 + helper(i, amount - coins[i])
                cache[(i, amount)] = min(include, cache[(i, amount)])
            return cache[(i, amount)]
        ans = helper(0, amount)
        if ans != float('inf'): return ans
        return -1

