def jump(nums):
    jump = 0
    farthest = float('-inf')
    end = 0

    for i in range(len(nums)):
        farthest = max(farthest, nums[i]) + 1
        if i == end and i != len(nums) - 1:
            jump += 1
            end = farthest

    return jump

