class Node:
    def __init__(self, data):

        self.data = data
        self.next = None
def reverse(head):
    curr=head
    prev=None
    while curr is not None:
        temp=curr.next
        curr.next=prev
        prev=curr
        curr=temp
    return prev
def rearrangeList(head):
    temp=head
    while temp:
        temp.next=reverse(temp.next)
        temp=temp.next
    return head

