another solution that I found: class Solution:
    def minWindow(self, s: str, t: str) -> str:
        if len(s) < len(t): return ""
        tdict, match, l, start, windowLenS = Counter(t), 0, 0, 0, len(s) + 1
        for r, ch in enumerate(s):
            if ch in tdict:
                tdict[ch] -= 1
                if tdict[ch] == 0:
                    match += 1
            while match == len(tdict):
                if windowLenS > r - l + 1:
                    start, windowLenS = l, r - l + 1
                removeCh = s[l]
                l += 1 
                if removeCh in tdict:
                    if tdict[removeCh] == 0:
                        match -= 1
                    tdict[removeCh] += 1
        if windowLenS <= len(s):
            return s[start:start + windowLenS]
        else:
            return ""

